import sys

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    inputStr = input[1]
    vPositions = [0] * n
    kPositions = [0] * n
    xPositions = [0] * n
    vCount = 0
    kCount = 0
    xCount = 0

    for i in range(n):
        ch = inputStr[i]
        if ch == 'V':
            vPositions[vCount] = i
            vCount += 1
        elif ch == 'K':
            kPositions[kCount] = i
            kCount += 1
        else:
            xPositions[xCount] = i
            xCount += 1

    # Initialize 4D DP array
    # Using a dictionary for memory efficiency
    from math import inf
    dp = {}
    def get_dp(i, j, k, d):
        return dp.get((i, j, k, d), inf)

    def set_dp(i, j, k, d, value):
        dp[(i, j, k, d)] = value

    set_dp(0, 0, 0, 0, 0)

    def countLess(arr, start, val):
        count = 0
        for i in range(start, len(arr)):
            if arr[i] < val:
                count += 1
        return count

    for vIdx in range(vCount + 1):
        for kIdx in range(kCount + 1):
            for xIdx in range(xCount + 1):
                for t in range(2):
                    cost = get_dp(vIdx, kIdx, xIdx, t)
                    if cost == inf:
                        continue
                    if vIdx < vCount:
                        posV = vPositions[vIdx]
                        moves = (countLess(vPositions, vIdx, posV) +
                                 countLess(kPositions, kIdx, posV) +
                                 countLess(xPositions, xIdx, posV))
                        new_cost = cost + moves
                        prev = get_dp(vIdx + 1, kIdx, xIdx, 1)
                        if new_cost < prev:
                            set_dp(vIdx + 1, kIdx, xIdx, 1, new_cost)
                    if kIdx < kCount and t == 0:
                        posK = kPositions[kIdx]
                        moves = (countLess(vPositions, vIdx, posK) +
                                 countLess(kPositions, kIdx, posK) +
                                 countLess(xPositions, xIdx, posK))
                        new_cost = cost + moves
                        prev = get_dp(vIdx, kIdx + 1, xIdx, 0)
                        if new_cost < prev:
                            set_dp(vIdx, kIdx + 1, xIdx, 0, new_cost)
                    if xIdx < xCount:
                        posX = xPositions[xIdx]
                        moves = (countLess(vPositions, vIdx, posX) +
                                 countLess(kPositions, kIdx, posX) +
                                 countLess(xPositions, xIdx, posX))
                        new_cost = cost + moves
                        prev = get_dp(vIdx, kIdx, xIdx + 1, 0)
                        if new_cost < prev:
                            set_dp(vIdx, kIdx, xIdx + 1, 0, new_cost)

    minCost = inf
    for i in range(2):
        minCost = min(minCost, get_dp(vCount, kCount, xCount, i))
    print(minCost)

if __name__ == "__main__":
    main()

